275	func recordServedFactsWithLockTimeout(errW io.Writer, at time.Time, brainDir, branch, surface, head, taskText string, factIDs []string, lockTimeout time.Duration) {
276		if brainDir == "" || len(factIDs) == 0 {
277			return
278		}
279		taskSHA := vitalityTaskHash(taskText)
280		events := make([]vitalityEvent, 0, len(factIDs))
281		for _, id := range factIDs {
282			if strings.TrimSpace(id) == "" {
283				continue
284			}
285			events = append(events, vitalityEvent{
286				Type:    vitalityEventServed,
287				FactID:  id,
288				At:      at,
289				Surface: surface,
290				TaskSHA: taskSHA,
291				Head:    head,
292				Branch:  branch,
293			})
294		}
295		if err := appendVitalityEventsBoundedWithLockTimeout(
296			brainDir, branch, events, factsVitalityLogMaxBytes, lockTimeout,
297		); err != nil && errW != nil && !errors.Is(err, brainstore.ErrFileLockTimeout) {
298			// A lock-timeout drop is the designed best-effort path under contention
299			// (bounded budget) and would spam stderr during normal concurrency, so
300			// it stays silent. Any other error is a real failed append (receipts
301			// dropped) or a failed inline compaction after a successful append;
302			// either way it is one bounded line per invocation and never a read
303			// failure.
304			fmt.Fprintf(errW, "warning: memories vitality recording degraded: %v\n", err)
305		}
306	}
